const vendas = $input.all();
let total = 0;
let maior = vendas[0].json;

for (const item of vendas) {
  const venda = item.json;
  total += venda.valor;
  if (venda.valor > maior.valor) maior = venda;
}

return [{ json: {
  quantidade: vendas.length,
  total,
  media: total / vendas.length,
  maior_venda: maior.valor,
  vendedor_da_maior: maior.vendedor
} }];
